function blockMessage(form: FormState): string {
  if (!form.maKh.trim()) return 'Bạn chưa nhập mã đối tượng';
  if (!form.maNx.trim()) return 'Bạn chưa nhập tài có ';
  if (!form.suaThue) {
    if (!form.soCt0.trim()) return 'Bạn chưa nhập số hóa đơn VAT';
    if (!form.soSeri0.trim()) return 'Bạn chưa nhập số seri hóa đơn VAT';
    if (!form.ngayCt0.trim() || form.ngayCt0 === VAT_SENTINEL) return 'Bạn chưa nhập ngày hóa đơn VAT';
  }
  for (const line of form.lines) {
    if (!line.maKhoI.trim()) return 'Bạn chưa nhập kho nhập ';
    if (!line.tkVt.trim()) return 'Bạn chưa nhập tài khoản nợ';
  }
  return '';
}

function toWrite(form: FormState, mode: 'create' | 'copy' | 'edit'): PncExpenseReceiptWrite {
  const lines: PncExpenseReceiptWriteLine[] = form.lines.map(line => {
    const row: PncExpenseReceiptWriteLine = {
      maVt: textOrNull(line.maVt),
      maVitri: textOrNull(line.maVitri),
      maKhoI: textOrNull(line.maKhoI),
      cpNt: num(line.cpNt),
      cp: num(line.cp),
      soLuongHg: num(line.soLuongHg),
      tienHg: num(line.tienHg),
      tienHgNt: num(line.tienHgNt),
      tkVt: textOrNull(line.tkVt),
      maVvI: textOrNull(line.maVvI),
      maHdI: textOrNull(line.maHdI),
      maPhiI: textOrNull(line.maPhiI),
      maTtlnI: textOrNull(line.maTtlnI),
      maTtcpI: textOrNull(line.maTtcpI),
      maBpI: textOrNull(line.maBpI),
    };
    const sendLinks = mode === 'copy' || (mode === 'edit' && line.sttRec0.trim().length > 0);
    if (mode === 'edit' && line.sttRec0.trim()) row.sttRec0 = line.sttRec0.trim();
    if (sendLinks) {
      row.sttRecPn = textOrNull(line.sttRecPn);
      row.sttRec0Pn = textOrNull(line.sttRec0Pn);
      row.soPn = textOrNull(line.soPn);
      row.ngayPn = dateOrNull(line.ngayPn);
    }
    return row;
  });
  const taxLines: PncExpenseReceiptWriteTaxLine[] = form.taxLines.map(line => {
    const row: PncExpenseReceiptWriteTaxLine = {
      tkThueNo: textOrNull(line.tkThueNo),
      tThueNt: num(line.tThueNt),
      tThue: num(line.tThue),
      diaChi: textOrNull(line.diaChi),
      soSo: textOrNull(line.soSo),
      soPo: textOrNull(line.soPo),
      soRo: textOrNull(line.soRo),
      soVt: textOrNull(line.soVt),
    };
    if (mode === 'edit' && line.sttRec0.trim()) row.sttRec0 = line.sttRec0.trim();
    return row;
  });
  return {
    maCt: 'PNC',
    maGd: form.maGd,
    maPost: form.maPost,
    maQuyen: textOrNull(form.maQuyen),
    ngayCt: dateOrNull(form.ngayCt),
    ngayLct: dateOrNull(form.ngayLct),
    soCt: textOrNull(form.soCt),
    soCt0: textOrNull(form.soCt0),
    soSeri0: textOrNull(form.soSeri0),
    ngayCt0: dateOrNull(form.ngayCt0),
    soLo: textOrNull(form.soLo),
    ngayLo: dateOrNull(form.ngayLo),
    maKh: textOrNull(form.maKh),
    ongBa: textOrNull(form.ongBa),
    diaChi: textOrNull(form.diaChi),
    maSoThue: textOrNull(form.maSoThue),
    dienGiai: textOrNull(form.dienGiai),
    tenKhVat: textOrNull(form.tenKhVat),
    diaChiVat: textOrNull(form.diaChiVat),
    tenVtThue: textOrNull(form.tenVtThue),
    maBpH: textOrNull(form.maBpH),
    maHsH: textOrNull(form.maHsH),
    maNx: textOrNull(form.maNx),
    maNt: textOrNull(form.maNt),
    tyGia: num(form.tyGia),
    mauBc: textOrNull(form.mauBc),
    suaThue: form.suaThue ? 1 : 0,
    suaTkThue: form.suaTkThue ? 1 : 0,
    suaCp: form.suaCp ? 1 : 0,
    pbCpSl: form.pbCpSl ? 1 : 0,
    pbCpTien: form.pbCpTien ? 1 : 0,
    maThue: textOrNull(form.maThue),
    thueSuat: num(form.thueSuat),
    tkThueCo: textOrNull(form.tkThueCo),
    tkThueNo: textOrNull(form.tkThueNo),
    hanTt: num(form.hanTt),
    lenhSo: textOrNull(form.lenhSo),
    lenhPo: textOrNull(form.lenhPo),
    lenhRo: textOrNull(form.lenhRo),
    lenhVt: textOrNull(form.lenhVt),
    tSoLuong: form.tSoLuong,
    tTienNt: form.tTienNt,
    tTien: form.tTien,
    tCpNt: form.tCpNt,
    tCp: form.tCp,
    tThueNt: form.tThueNt,
    tThue: form.tThue,
    soHdGtgt: form.soHdGtgt,
    tTtNt: form.tTtNt,
    tTt: form.tTt,
    lines,
    taxLines,
  };
}

const PncFormPage: React.FC = () => {
  const navigate = useInAppNavigate();
  const dispatch = useAppDispatch();
  const { sttRec } = useParams();
  const [searchParams] = useSearchParams();
  const mode = searchParams.get('mode');
  const copyFrom = searchParams.get('copyFrom') ?? '';
  const isView = Boolean(sttRec) && mode === 'view';
  const isCopy = !sttRec && copyFrom.length > 0;
  const isNew = !sttRec;
  const readOnly = isView;
  const [form, setForm] = useState<FormState>(emptyForm);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [missing, setMissing] = useState(false);
  const [selectedLine, setSelectedLine] = useState(-1);
  const [selectedTax, setSelectedTax] = useState(-1);
  const { onDirtyChange, guardedNavigate, leaveConfirmModalProps } = useFormLeaveGuard({ message: LEAVE_MESSAGE });
  const { markDirty, markClean } = useDirtyTracking(isView ? undefined : onDirtyChange);

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      if (!sttRec && !copyFrom) {
        setForm(emptyForm());
        setMissing(false);
        setError('');
        markClean();
        return;
      }
      setLoading(true);
      setError('');
      setMissing(false);
      try {
        const dto = await getPncExpenseReceipt(sttRec || copyFrom);
        if (cancelled) return;
        setForm(formFromApi(dto, isCopy));
        markClean();
      } catch (err) {
        if (cancelled) return;
        setMissing(true);
        setError(getApiErrorMessage(err, 'Không tìm thấy phiếu nhập chi phí'));
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    void load();
    return () => {
      cancelled = true;
    };
  }, [sttRec, copyFrom, isCopy, markClean]);

  const touch = (next: FormState) => {
    setForm(next);
    if (!readOnly) markDirty();
  };

  const setField = <K extends keyof FormState>(key: K, value: FormState[K]) => {
    touch({ ...form, [key]: value });
  };

  const setLine = (index: number, patch: Partial<LineState>) => {
    const lines = form.lines.map((line, i) => (i === index ? { ...line, ...patch } : line));
    touch({ ...form, lines });
  };

  const setTax = (index: number, patch: Partial<TaxState>) => {
    const taxLines = form.taxLines.map((line, i) => (i === index ? { ...line, ...patch } : line));
    touch({ ...form, taxLines });
  };

  const onBlurCustomer = async () => {
    const code = form.maKh.trim();
    if (!code) {
      setForm(prev => ({ ...prev, tenKh: '' }));
      return;
    }
    try {
      const res = await ktService.searchCustomers({ search: code, page: 1, pageSize: 20, isActive: true });
      const hit = res.items.find(item => item.code.trim().toLowerCase() === code.toLowerCase());
      setForm(prev => ({ ...prev, tenKh: hit?.name ?? '' }));
    } catch {
      /* tra cứu không chặn gõ */
    }
  };

  const onBlurAccount = async () => {
    const code = form.maNx.trim();
    if (!code) {
      setForm(prev => ({ ...prev, tenNx: '' }));
      return;
    }
    try {
      const res = await ktService.searchAccounts({ search: code, page: 1, pageSize: 20, isActive: true });
      const hit = res.items.find(item => item.code.trim().toLowerCase() === code.toLowerCase());
      setForm(prev => ({ ...prev, tenNx: hit?.name ?? '' }));
    } catch {
      /* tra cứu không chặn gõ */
    }
  };

  const onSave = async () => {
    const blocked = blockMessage(form);
    if (blocked) {
      setError(blocked);
      dispatchAppToast(dispatch, { type: 'error', message: blocked });
      return;
    }
    setSaving(true);
    setError('');
    try {
      const writeMode = isCopy ? 'copy' : isNew ? 'create' : 'edit';
      const body = toWrite(form, writeMode);
      const saved = isNew
        ? await createPncExpenseReceipt(body)
        : await updatePncExpenseReceipt(sttRec ?? '', body);
      markClean();
      dispatchAppToast(dispatch, { type: 'success', message: 'Đã lưu phiếu nhập chi phí' });
      navigate(`/kt/pnc/${saved.sttRec}`);
      if (!isNew) {
        const fresh = await getPncExpenseReceipt(saved.sttRec);
        setForm(formFromApi(fresh, false));
        markClean();
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : getApiErrorMessage(err, 'Lưu thất bại');
      setError(message);
      dispatchAppToast(dispatch, { type: 'error', message });
    } finally {
      setSaving(false);
    }
  };

  const title = isView
    ? 'Xem phiếu nhập chi phí'
    : isNew
      ? 'Thêm phiếu nhập chi phí'
      : 'Sửa phiếu nhập chi phí';

  return (
    <div className={df.page} data-testid="ct-pnc-form">
      <DocumentFormHeader
        title={title}
        isNew={isNew}
        isReadOnly={readOnly}
        saving={saving}
        testIdPrefix="ct-pnc"
        saveLabel="Lưu"
        saveEditLabel="Lưu"
        onBack={() => guardedNavigate(() => navigate('/kt/pnc'))}
        onSave={missing || readOnly ? undefined : onSave}
      />
      {error && <div className={df.errorBanner}>{error}</div>}
      {loading && <div className={df.loading}>Đang tải...</div>}
      {!missing && !loading && (
        <>
          <section className={df.section}>
            <h2 className={df.sectionTitle}>Chứng từ</h2>
            <div className={df.row4}>
              <Select label="Loại giao dịch" disabled={readOnly} data-testid="ct-pnc-field-maGd" value={form.maGd} options={[{ value: '1', label: 'Nhập chi phí' }]} onChange={event => setField('maGd', event.target.value)} />
              <Select label="Trạng thái" disabled={readOnly} data-testid="ct-pnc-field-maPost" value={form.maPost} options={[{ value: '3', label: 'Lập chứng từ' }, { value: '9', label: 'Hạch toán sổ cái' }]} onChange={event => setField('maPost', event.target.value)} />
              <div><label className={df.label}>Quyền số</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pnc-field-maQuyen" value={form.maQuyen} onChange={event => setField('maQuyen', event.target.value)} /></div>
              <div><label className={df.label}>Ngày C.từ</label><Input disabled={readOnly} type="date" data-testid="ct-pnc-field-ngayCt" value={form.ngayCt} onChange={event => setField('ngayCt', event.target.value)} /></div>
              <div><label className={df.label}>Ngày lập</label><Input disabled={readOnly} type="date" data-testid="ct-pnc-field-ngayLct" value={form.ngayLct} onChange={event => setField('ngayLct', event.target.value)} /></div>
              <div><label className={df.label}>Số C.từ</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pnc-field-soCt" value={form.soCt} onChange={event => setField('soCt', event.target.value)} /></div>
              <div><label className={df.label}>Số hóa đơn VAT</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pnc-field-soCt0" value={form.soCt0} onChange={event => setField('soCt0', event.target.value)} /></div>
              <div><label className={df.label}>Số seri hóa đơn VAT</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pnc-field-soSeri0" value={form.soSeri0} onChange={event => setField('soSeri0', event.target.value)} /></div>
              <div><label className={df.label}>Ngày hóa đơn VAT</label><Input disabled={readOnly} type="date" data-testid="ct-pnc-field-ngayCt0" value={form.ngayCt0} onChange={event => setField('ngayCt0', event.target.value)} /></div>
              <div><label className={df.label}>Số lô</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pnc-field-soLo" value={form.soLo} onChange={event => setField('soLo', event.target.value)} /></div>
              <div><label className={df.label}>Ngày lô</label><Input disabled={readOnly} type="date" data-testid="ct-pnc-field-ngayLo" value={form.ngayLo} onChange={event => setField('ngayLo', event.target.value)} /></div>
              <div><label className={df.label}>Mẫu báo cáo</label><Input disabled={readOnly} maxLength={10} data-testid="ct-pnc-field-mauBc" value={form.mauBc} onChange={event => setField('mauBc', event.target.value)} /></div>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Đối tượng</h2>
            <div className={df.row4}>
              <div><label className={df.label}>Đối tượng</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pnc-field-maKh" value={form.maKh} onChange={event => setField('maKh', event.target.value)} onBlur={() => { void onBlurCustomer(); }} /></div>
              <div><label className={df.label}>Tên đối tượng</label><Input disabled data-testid="ct-pnc-field-tenKh" value={form.tenKh} onChange={() => undefined} /></div>
              <div><label className={df.label}>Người giao</label><Input disabled={readOnly} maxLength={200} data-testid="ct-pnc-field-ongBa" value={form.ongBa} onChange={event => setField('ongBa', event.target.value)} /></div>
              <div><label className={df.label}>Địa chỉ</label><Input disabled={readOnly} maxLength={200} data-testid="ct-pnc-field-diaChi" value={form.diaChi} onChange={event => setField('diaChi', event.target.value)} /></div>
              <div><label className={df.label}>Mã số thuế</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pnc-field-maSoThue" value={form.maSoThue} onChange={event => setField('maSoThue', event.target.value)} /></div>
              <div className={df.spanCol2}><label className={df.label}>Diễn giải</label><Input disabled={readOnly} maxLength={200} data-testid="ct-pnc-field-dienGiai" value={form.dienGiai} onChange={event => setField('dienGiai', event.target.value)} /></div>
              <div><label className={df.label}>Tên khách VAT</label><Input disabled={readOnly} maxLength={200} data-testid="ct-pnc-field-tenKhVat" value={form.tenKhVat} onChange={event => setField('tenKhVat', event.target.value)} /></div>
              <div><label className={df.label}>Địa chỉ VAT</label><Input disabled={readOnly} maxLength={200} data-testid="ct-pnc-field-diaChiVat" value={form.diaChiVat} onChange={event => setField('diaChiVat', event.target.value)} /></div>
              <div><label className={df.label}>Tên hàng thuế</label><Input disabled={readOnly} maxLength={200} data-testid="ct-pnc-field-tenVtThue" value={form.tenVtThue} onChange={event => setField('tenVtThue', event.target.value)} /></div>
              <div><label className={df.label}>Bộ phận</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pnc-field-maBpH" value={form.maBpH} onChange={event => touch({ ...form, maBpH: event.target.value, tenBpH: '' })} /></div>
              <div><label className={df.label}>Tên bộ phận</label><Input disabled data-testid="ct-pnc-field-tenBpH" value={form.tenBpH} onChange={() => undefined} /></div>
              <div><label className={df.label}>Hồ sơ</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pnc-field-maHsH" value={form.maHsH} onChange={event => touch({ ...form, maHsH: event.target.value, tenHsH: '' })} /></div>
              <div><label className={df.label}>Tên hồ sơ</label><Input disabled data-testid="ct-pnc-field-tenHsH" value={form.tenHsH} onChange={() => undefined} /></div>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Tài khoản và tiền tệ</h2>
            <div className={df.row4}>
              <div><label className={df.label}>Tài khoản có</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pnc-field-maNx" value={form.maNx} onChange={event => setField('maNx', event.target.value)} onBlur={() => { void onBlurAccount(); }} /></div>
              <div><label className={df.label}>Tên tài khoản có</label><Input disabled data-testid="ct-pnc-field-tenNx" value={form.tenNx} onChange={() => undefined} /></div>
              <div><label className={df.label}>Ngoại tệ</label><Input disabled={readOnly} maxLength={3} data-testid="ct-pnc-field-maNt" value={form.maNt} onChange={event => setField('maNt', event.target.value)} /></div>
              <div><label className={df.label}>Tỷ giá</label><Input disabled={readOnly} inputMode="decimal" data-testid="ct-pnc-field-tyGia" value={form.tyGia} onChange={event => setField('tyGia', event.target.value)} /></div>
              <div><label className={df.label}>Mã thuế</label><Input disabled={readOnly} maxLength={10} data-testid="ct-pnc-field-maThue" value={form.maThue} onChange={event => setField('maThue', event.target.value)} /></div>
              <div><label className={df.label}>Thuế suất</label><Input disabled={readOnly} inputMode="decimal" data-testid="ct-pnc-field-thueSuat" value={form.thueSuat} onChange={event => setField('thueSuat', event.target.value)} /></div>
              <div><label className={df.label}>Tài khoản thuế có</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pnc-field-tkThueCo" value={form.tkThueCo} onChange={event => setField('tkThueCo', event.target.value)} /></div>
              <div><label className={df.label}>Tài khoản thuế nợ</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pnc-field-tkThueNo" value={form.tkThueNo} onChange={event => setField('tkThueNo', event.target.value)} /></div>
              <div><label className={df.label}>Hạn thanh toán</label><Input disabled={readOnly} inputMode="decimal" data-testid="ct-pnc-field-hanTt" value={form.hanTt} onChange={event => setField('hanTt', event.target.value)} /></div>
              <div><label className={df.label}>Lệnh số</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pnc-field-lenhSo" value={form.lenhSo} onChange={event => setField('lenhSo', event.target.value)} /></div>
              <div><label className={df.label}>Lệnh PO</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pnc-field-lenhPo" value={form.lenhPo} onChange={event => setField('lenhPo', event.target.value)} /></div>
              <div><label className={df.label}>Lệnh RO</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pnc-field-lenhRo" value={form.lenhRo} onChange={event => setField('lenhRo', event.target.value)} /></div>
              <div><label className={df.label}>Lệnh VT</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pnc-field-lenhVt" value={form.lenhVt} onChange={event => setField('lenhVt', event.target.value)} /></div>
              <Checkbox label="Sửa thuế" disabled={readOnly} data-testid="ct-pnc-field-suaThue" checked={form.suaThue} onChange={event => setField('suaThue', event.target.checked)} />
              <Checkbox label="Sửa TK thuế" disabled={readOnly} data-testid="ct-pnc-field-suaTkThue" checked={form.suaTkThue} onChange={event => setField('suaTkThue', event.target.checked)} />
              <Checkbox label="Sửa CP" disabled={readOnly} data-testid="ct-pnc-field-suaCp" checked={form.suaCp} onChange={event => setField('suaCp', event.target.checked)} />
              <Checkbox label="Phân bổ CP theo SL" disabled={readOnly} data-testid="ct-pnc-field-pbCpSl" checked={form.pbCpSl} onChange={event => setField('pbCpSl', event.target.checked)} />
              <Checkbox label="Phân bổ CP theo tiền" disabled={readOnly} data-testid="ct-pnc-field-pbCpTien" checked={form.pbCpTien} onChange={event => setField('pbCpTien', event.target.checked)} />
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Tổng</h2>
            <div className={df.row4}>
              <div><label className={df.label}>Tổng số lượng</label><Input disabled data-testid="ct-pnc-field-tSoLuong" value={showMoney(form.tSoLuong)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Tổng Ps NT</label><Input disabled data-testid="ct-pnc-field-tTienNt" value={showMoney(form.tTienNt)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Tổng Phát sinh</label><Input disabled data-testid="ct-pnc-field-tTien" value={showMoney(form.tTien)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Chi phí NT</label><Input disabled data-testid="ct-pnc-field-tCpNt" value={showMoney(form.tCpNt)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Chi phí</label><Input disabled data-testid="ct-pnc-field-tCp" value={showMoney(form.tCp)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Tiền thuế NT</label><Input disabled data-testid="ct-pnc-field-tThueNt" value={showMoney(form.tThueNt)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Tiền thuế</label><Input disabled data-testid="ct-pnc-field-tThue" value={showMoney(form.tThue)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Số HĐ GTGT</label><Input disabled data-testid="ct-pnc-field-soHdGtgt" value={String(form.soHdGtgt)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Thanh toán NT</label><Input disabled data-testid="ct-pnc-field-tTtNt" value={showMoney(form.tTtNt)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Thanh toán</label><Input disabled data-testid="ct-pnc-field-tTt" value={showMoney(form.tTt)} onChange={() => undefined} /></div>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Dòng hàng</h2>
            {!readOnly && (
              <div>
                <Button className={df.btnAddLine} data-testid="ct-pnc-line-add-btn" onClick={() => { touch({ ...form, lines: [...form.lines, emptyLine()] }); setSelectedLine(form.lines.length); }}>Thêm dòng</Button>
                <Button className={df.btnDeleteLine} data-testid="ct-pnc-line-remove-btn" disabled={selectedLine < 0} onClick={() => { const lines = form.lines.filter((_, i) => i !== selectedLine); touch({ ...form, lines }); setSelectedLine(-1); }}>Xóa dòng</Button>
              </div>
            )}
            <div className={df.tableWrapper}>
              <table className={df.linesTable} data-testid="ct-pnc-line-grid">
                <thead>
                  <tr>
                    <th>Hàng hoá</th><th>Tên hàng hoá</th><th>ĐVT</th><th>Vị trí</th><th>Kho</th>
                    <th>Chi Phí</th><th>Thành tiền</th><th>Sl Hàng</th><th>Tiền hàng (VNĐ)</th><th>Tiền hàng</th><th>Tk Nợ</th>
                    <th>V.Việc</th><th>Hợp đồng</th><th>khoản mục</th><th>Trung tâm lợi nhuận</th><th>Trung tâm chi phí</th><th>Phòng ban</th>
                  </tr>
                </thead>
                <tbody>
                  {form.lines.map((line, i) => {
                    const selected = i === selectedLine;
                    return (
                      <tr key={`${line.sttRec0}-${i}`} aria-selected={selected} style={selected ? { background: 'var(--ds-color-primary-bg, rgba(13, 110, 253, 0.08))' } : undefined} onClick={() => setSelectedLine(i)}>
                        <td><Input disabled maxLength={30} data-testid={`ct-pnc-line-${i}-maVt`} value={line.maVt} onChange={() => undefined} /></td>
                        <td><Input disabled data-testid={`ct-pnc-line-${i}-tenVt`} value={line.tenVt} onChange={() => undefined} /></td>
                        <td><Input disabled data-testid={`ct-pnc-line-${i}-dvt`} value={line.dvt} onChange={() => undefined} /></td>
                        <td><Input disabled maxLength={30} data-testid={`ct-pnc-line-${i}-maVitri`} value={line.maVitri} onChange={() => undefined} /></td>
                        <td><Input disabled maxLength={30} data-testid={`ct-pnc-line-${i}-maKhoI`} value={line.maKhoI} onChange={() => undefined} /></td>
                        <td><Input disabled inputMode="decimal" data-testid={`ct-pnc-line-${i}-cpNt`} value={line.cpNt} onChange={() => undefined} /></td>
                        <td><Input disabled inputMode="decimal" data-testid={`ct-pnc-line-${i}-cp`} value={line.cp} onChange={() => undefined} /></td>
                        <td><Input disabled inputMode="decimal" data-testid={`ct-pnc-line-${i}-soLuongHg`} value={line.soLuongHg} onChange={() => undefined} /></td>
                        <td><Input disabled inputMode="decimal" data-testid={`ct-pnc-line-${i}-tienHg`} value={line.tienHg} onChange={() => undefined} /></td>
                        <td><Input disabled inputMode="decimal" data-testid={`ct-pnc-line-${i}-tienHgNt`} value={line.tienHgNt} onChange={() => undefined} /></td>
                        <td><Input disabled maxLength={30} data-testid={`ct-pnc-line-${i}-tkVt`} value={line.tkVt} onChange={() => undefined} /></td>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pnc-line-${i}-maVvI`} value={line.maVvI} onChange={event => setLine(i, { maVvI: event.target.value })} /></td>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pnc-line-${i}-maHdI`} value={line.maHdI} onChange={event => setLine(i, { maHdI: event.target.value })} /></td>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pnc-line-${i}-maPhiI`} value={line.maPhiI} onChange={event => setLine(i, { maPhiI: event.target.value })} /></td>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pnc-line-${i}-maTtlnI`} value={line.maTtlnI} onChange={event => setLine(i, { maTtlnI: event.target.value })} /></td>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pnc-line-${i}-maTtcpI`} value={line.maTtcpI} onChange={event => setLine(i, { maTtcpI: event.target.value })} /></td>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pnc-line-${i}-maBpI`} value={line.maBpI} onChange={event => setLine(i, { maBpI: event.target.value })} /></td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Thuế GTGT đầu vào</h2>
            {!readOnly && (
              <div>
                <Button className={df.btnAddLine} data-testid="ct-pnc-tax-add-btn" onClick={() => { touch({ ...form, taxLines: [...form.taxLines, emptyTax()] }); setSelectedTax(form.taxLines.length); }}>Thêm dòng thuế</Button>
                <Button className={df.btnDeleteLine} data-testid="ct-pnc-tax-remove-btn" disabled={selectedTax < 0} onClick={() => { const taxLines = form.taxLines.filter((_, i) => i !== selectedTax); touch({ ...form, taxLines }); setSelectedTax(-1); }}>Xóa dòng thuế</Button>
              </div>
            )}
            <div className={df.tableWrapper}>
              <table className={df.linesTable} data-testid="ct-pnc-tax-grid">
                <thead>
                  <tr>
                    <th>TK thuế nợ</th><th>Tiền thuế NT</th><th>Tiền thuế</th><th>Địa chỉ</th>
                    <th>Lệnh số</th><th>Lệnh PO</th><th>Lệnh RO</th><th>Lệnh VT</th>
                  </tr>
                </thead>
                <tbody>
                  {form.taxLines.map((line, j) => {
                    const selected = j === selectedTax;
                    return (
                      <tr key={`${line.sttRec0}-${j}`} aria-selected={selected} style={selected ? { background: 'var(--ds-color-primary-bg, rgba(13, 110, 253, 0.08))' } : undefined} onClick={() => setSelectedTax(j)}>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pnc-tax-${j}-tkThueNo`} value={line.tkThueNo} onChange={event => setTax(j, { tkThueNo: event.target.value })} /></td>
                        <td><Input disabled={readOnly} inputMode="decimal" data-testid={`ct-pnc-tax-${j}-tThueNt`} value={line.tThueNt} onChange={event => setTax(j, { tThueNt: event.target.value })} /></td>
                        <td><Input disabled={readOnly} inputMode="decimal" data-testid={`ct-pnc-tax-${j}-tThue`} value={line.tThue} onChange={event => setTax(j, { tThue: event.target.value })} /></td>
                        <td><Input disabled={readOnly} maxLength={200} data-testid={`ct-pnc-tax-${j}-diaChi`} value={line.diaChi} onChange={event => setTax(j, { diaChi: event.target.value })} /></td>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pnc-tax-${j}-soSo`} value={line.soSo} onChange={event => setTax(j, { soSo: event.target.value })} /></td>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pnc-tax-${j}-soPo`} value={line.soPo} onChange={event => setTax(j, { soPo: event.target.value })} /></td>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pnc-tax-${j}-soRo`} value={line.soRo} onChange={event => setTax(j, { soRo: event.target.value })} /></td>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pnc-tax-${j}-soVt`} value={line.soVt} onChange={event => setTax(j, { soVt: event.target.value })} /></td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </section>

          <div className={df.footer}>
            <span className={df.totalLabel}>Thanh toán</span>
            <span className={df.totalValue}>{showMoney(form.tTt)}</span>
          </div>
        </>
      )}
      <LeaveConfirmModal {...leaveConfirmModalProps} />
    </div>
  );
};

export default PncFormPage;
