function withQuery(path: string, query: Record<string, string | number | boolean>): string {
  const params = new URLSearchParams();
  Object.entries(query).forEach(([key, value]) => {
    params.set(key, String(value));
  });
  const qs = params.toString();
  return qs ? `${path}?${qs}` : path;
}

export async function listPncExpenseReceipts(
  query: Record<string, string | number | boolean>,
): Promise<PncExpenseReceiptListItem[]> {
  const res = await apiClient.get<BffResponse<PncExpenseReceiptListItem[]>>(withQuery(BASE, query));
  return unwrap(res);
}

export async function getPncExpenseReceipt(sttRec: string): Promise<PncExpenseReceipt> {
  const res = await apiClient.get<BffResponse<PncExpenseReceipt>>(`${BASE}/${encodeURIComponent(sttRec)}`);
  return unwrap(res);
}

export async function createPncExpenseReceipt(body: PncExpenseReceiptWrite): Promise<PncExpenseReceipt> {
  const res = await apiClient.post<BffResponse<PncExpenseReceipt>>(BASE, body);
  return unwrap(res);
}

export async function updatePncExpenseReceipt(sttRec: string, body: PncExpenseReceiptWrite): Promise<PncExpenseReceipt> {
  const res = await apiClient.put<BffResponse<PncExpenseReceipt>>(`${BASE}/${encodeURIComponent(sttRec)}`, body);
  return unwrap(res);
}
